library;

import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

/// Scratch check (review): does the persisted session JSONL assistant
/// record still contain the ledger after the gh-1516 fold?
void main() {
  const ledgerAnswer =
      '''
Task complete.
```task-ledger
- requirement: create script.py
  command: test -f script.py
  expected: exit 0
  actual: exit 0
  status: pass
```
''';

  test('disk assistant record content', () async {
    final env = MemoryExecutionEnv(cwd: '/work');
    await env.writeFile('/work/.fah/memory/.last_maintenance', '');
    await env.writeFile('/work/key.txt', 'x');
    final io = FakeCliIO();
    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: 'test-key',
        env: env,
        sessionRoot: '/sessions',
        providerKind: 'openai-completions',
        approvalMode: ApprovalMode.unattended,
        headlessRun: true,
      ),
      io: io,
      streamFunction: FakeStreamFunction([
        toolTurn([
          ToolCall(id: 'c1', name: 'read', arguments: const {'path': 'key.txt'}),
        ]),
        textTurn(ledgerAnswer),
      ]).call,
    );
    final exitCode = await cli.runHeadless('do it');
    expect(exitCode, 0);
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    final sessions = await repo.list(cwd: '/work');
    final session = await repo.open(sessions.first);
    final records = await session.getEntries();
    final assistantRecords = [
      for (final r in records)
        if (r is MessageRecord && r.message is AssistantMessage) r,
    ];
    expect(assistantRecords, isNotEmpty);
    final lastText = (assistantRecords.last.message as AssistantMessage)
        .content
        .whereType<TextContent>()
        .map((b) => b.text)
        .join('\n');
    print('--- LAST ASSISTANT RECORD ON DISK ---');
    print(const JsonEncoder.withIndent(' ').convert(
      (assistantRecords.last.toJson()),
    ));
    expect(lastText, isNot(contains('task-ledger')),
        reason: 'disk record must be stripped');
  });
}

