void _onTextDelta(TextDeltaEvent assistantMessageEvent) {
  final delta = assistantMessageEvent.delta;
  if (_useTui || !_buffersAnswer) {
    // Live surfaces.
    if (!_useTui && _postToolHolds.isNotEmpty) {
