      final value = args[key];
      if (value is String && value.isNotEmpty) _touchedPaths.add(value);
    }
    final detail = toolRowDetail(
      toolName,
      args,
      cwd: _env.cwd,
      home: config.homeDir,
    );
    _toolStarts[toolCallId] = (DateTime.now(), detail);
