      :final toolName,
      :final result,
      :final isError,
    ):
      onToolExecutionEnd(toolCallId, toolName, result, isError: isError);
    case TurnEndEvent(:final message):
      onTurnEnd(message);
    case ModelRequestEvent():
      await onModelRequest?.call(event);
    case TaskLedgerEvent():
      await onTaskLedger?.call(event);
    default:
  }
}

