      return 'no obligation carries id $id. Open ids: '
          '${ids.isEmpty ? "(none)" : ids.join(", ")}';
    }
    try {
      await session.appendCustomEntry(
        customType: obligationsLedgerRecordType,
        data: payload,
      );
