String? _cancelShellJobById(String id, ShellJobRegistry jobs) {
  final shellJob = jobs.job(id);
  if (shellJob == null) return null;
  if (!shellJob.isRunning) {
    return '$id already finished (exit code ${shellJob.exitCode})';
